Scripts.OnEnter:
MBB_ShowTimeout = -1;
if( MBB_Options and MBB_Options.ShowTooltip == 0 ) then return; end
GameTooltip:SetOwner(self, "ANCHOR_LEFT");
GameTooltip:AddLine("MinimapButtonBag Reborn");
GameTooltip:AddLine(MBB_TOOLTIP1, 0, 1, 0);
GameTooltip:Show();

Scripts.OnDragStart:
if( MBB_Options.AttachToMinimap == 1 ) then
	MBB_DragFlag = 1;
elseif MBB_Options.DetachedButtonLocked ~= 1 then
	self:StartMoving();
end

Scripts.OnDragStop:
if( MBB_Options.AttachToMinimap == 1 ) then
	MBB_DragFlag = 0;
	local point,_,_,xpos,ypos = self:GetPoint();
	-- 3.3.5a fix: save the position at 100% size (see MBB_SetButtonPosition)
	local s = self:GetScale(); local half = self:GetWidth() / 2;
	MBB_Options.ButtonPos = {(xpos + half) * s - half, (ypos - half) * s + half};
	MBB_Options.DetachedButtonPos = point;
elseif MBB_Options.DetachedButtonLocked ~= 1 then
	self:StopMovingOrSizing();
	MBB_SnapDetachedButtonToScreen();
end

Scripts.OnValueChanged:
if( self:GetValue() == 0 ) then
	getglobal(self:GetName().."Text"):SetText(MBB_OPTIONS_SLIDEROFF);
else
	getglobal(self:GetName().."Text"):SetText(string.format("%.3f", self:GetValue()) .. " " .. MBB_OPTIONS_SLIDERSEK);
end

Scripts.OnShow:
self:SetValue(MBB_Options.CollapseTimeout);
if( MBB_Options.CollapseTimeout == 0 ) then
	getglobal(self:GetName().."Text"):SetText(MBB_OPTIONS_SLIDEROFF);
else
	getglobal(self:GetName().."Text"):SetText(self:GetValue() .. " " .. MBB_OPTIONS_SLIDERSEK);
end

Scripts.OnEnterPressed:
if( not tonumber(self:GetText()) ) then
	self:SetText(MBB_Options.MaxButtonsPerLine);
end
MBB_UpdateAltRadioButtons();
self:ClearFocus();

Scripts.OnShow:
if( MBB_Options.AltExpandDirection == 1 ) then
	MBB_RadioButton_OnClick(1, true);
end

if( MBB_Options.AltExpandDirection == 2 ) then
	MBB_RadioButton_OnClick(2, true);
end

if( MBB_Options.AltExpandDirection == 3 ) then
	MBB_RadioButton_OnClick(3, true);
end

if( MBB_Options.AltExpandDirection == 4 ) then
	MBB_RadioButton_OnClick(4, true);
end

Scripts.OnEvent:
if event == "PLAYER_REGEN_DISABLED" then
    MBB_SetCheckEnabled(self, false);
elseif event == "PLAYER_REGEN_ENABLED" then
    MBB_SetCheckEnabled(self, true);
end

Scripts.OnShow:
-- Text + style
local t = _G[self:GetName().."Text"];
if t then
    t:SetText(MBB_OPTIONS_DETACH or "Detach from Minimap");
    t:SetTextColor(1, 1, 1);
    t:ClearAllPoints();
    t:SetPoint("LEFT", self, "RIGHT", 2, 1);
    t:SetJustifyH("LEFT");
    t:SetWidth(230);
    t:SetWordWrap(false);
end

-- Checked state reflects current option (checked = detached)
if MBB_Options and MBB_Options.AttachToMinimap ~= nil then
    self:SetChecked(MBB_Options.AttachToMinimap == 0);
end

-- Disable in combat
if MBB_IsInCombat() then
    MBB_SetCheckEnabled(self, false);
end

Scripts.OnClick:
-- Block changes during combat
if MBB_IsInCombat() then
    if MBB_Options and MBB_Options.AttachToMinimap ~= nil then
        self:SetChecked(MBB_Options.AttachToMinimap == 0);
    end
    return;
end

if not MBB_Options then return end

if self:GetChecked() then
    -- Detach
    MBB_Options.AttachToMinimap = 0;
    MBB_Options.ButtonPos = {0, 0};
    MBB_Options.DetachedButtonPos = "CENTER";
    if not MBB_Options.DetachedButtonPos and MBB_DefaultOptions then
        MBB_Options.DetachedButtonPos = MBB_DefaultOptions.DetachedButtonPos;
    end
else
    -- Attach
    MBB_Options.AttachToMinimap = 1;
    if MBB_DefaultOptions then
        MBB_Options.ButtonPos = MBB_DefaultOptions.ButtonPos;
    end
end

if MBB_SetButtonPosition then
    MBB_SetButtonPosition();
end
if MBB_UpdatePositionOptionControls then
    MBB_UpdatePositionOptionControls();
end

Scripts.OnEnter:
GameTooltip:SetOwner(self, "ANCHOR_RIGHT");
GameTooltip:SetText(MBB_OPTIONS_DETACH or "Detach from Minimap", 1, 1, 1);
GameTooltip:AddLine(MBB_OPTIONS_DETACH_DESC or "Allows the MBB button to be freely moved on the screen.", nil, nil, nil, true);
if MBB_IsInCombat() then
    GameTooltip:AddLine(MBB_OPTIONS_DETACH_COMBAT or "Cannot be changed during combat.", 1, 0.3, 0.3, true);
end
GameTooltip:Show();

Scripts.OnShow:
local t = _G[self:GetName().."Text"];
if t then
    t:SetText(MBB_OPTIONS_LOCK_POSITION or "Lock detached position");
    t:SetTextColor(1, 1, 1);
    t:ClearAllPoints();
    t:SetPoint("LEFT", self, "RIGHT", 2, 1);
    t:SetJustifyH("LEFT");
    t:SetWidth(230);
    t:SetWordWrap(false);
end
MBB_UpdatePositionOptionControls();

Scripts.OnClick:
if not MBB_Options then return; end
if MBB_IsInCombat() then
    MBB_UpdatePositionOptionControls();
    return;
end
MBB_Options.DetachedButtonLocked = self:GetChecked() and 1 or 0;
MBB_SetButtonPosition();
MBB_UpdatePositionOptionControls();

Scripts.OnEnter:
GameTooltip:SetOwner(self, "ANCHOR_RIGHT");
GameTooltip:SetText(MBB_OPTIONS_LOCK_POSITION or "Lock detached position", 1, 1, 1);
GameTooltip:AddLine(MBB_OPTIONS_LOCK_POSITION_DESC or "Prevents accidentally moving the detached MBB button.", nil, nil, nil, true);
GameTooltip:Show();

Scripts.OnShow:
local t = _G[self:GetName().."Text"];
if t then
    t:SetText(MBB_OPTIONS_SNAP_EDGES or "Snap to WoW window edges");
    t:SetTextColor(1, 1, 1);
    t:ClearAllPoints();
    t:SetPoint("LEFT", self, "RIGHT", 2, 1);
    t:SetJustifyH("LEFT");
    t:SetWidth(230);
    t:SetWordWrap(false);
end
MBB_UpdatePositionOptionControls();

Scripts.OnClick:
if not MBB_Options then return; end
if MBB_IsInCombat() then
    MBB_UpdatePositionOptionControls();
    return;
end
MBB_Options.SnapToScreenEdges = self:GetChecked() and 1 or 0;
if MBB_Options.SnapToScreenEdges == 1 then
    MBB_SnapDetachedButtonToScreen();
end
MBB_UpdatePositionOptionControls();

Scripts.OnEnter:
GameTooltip:SetOwner(self, "ANCHOR_RIGHT");
GameTooltip:SetText(MBB_OPTIONS_SNAP_EDGES or "Snap to WoW window edges", 1, 1, 1);
GameTooltip:AddLine(MBB_OPTIONS_SNAP_EDGES_DESC or "Snaps the detached MBB button to nearby WoW window edges. WoW addons cannot detect physical monitor boundaries.", nil, nil, nil, true);
GameTooltip:Show();

Scripts.OnShow:
local t = _G[self:GetName().."Text"];
if t then
    t:SetText(MBB_OPTIONS_SHOW_TOOLTIP or "Show tooltip");
    t:SetTextColor(1, 1, 1);
    t:ClearAllPoints();
    t:SetPoint("LEFT", self, "RIGHT", 2, 1);
    t:SetJustifyH("LEFT");
    t:SetWidth(230);
    t:SetWordWrap(false);
end
self:SetChecked(not MBB_Options or MBB_Options.ShowTooltip ~= 0);

Scripts.OnEnter:
GameTooltip:SetOwner(self, "ANCHOR_RIGHT");
GameTooltip:SetText(MBB_OPTIONS_SHOW_TOOLTIP or "Show tooltip", 1, 1, 1);
GameTooltip:AddLine(MBB_OPTIONS_SHOW_TOOLTIP_DESC or "Shows the MBB tooltip when the mouse is over the MBB button.", nil, nil, nil, true);
GameTooltip:Show();

Scripts.OnLoad:
self:SetMinMaxValues(0.75, 1.50);
self:SetValueStep(0.05);
if self.SetObeyStepOnDrag then self:SetObeyStepOnDrag(true); end
_G[self:GetName().."Low"]:SetText("75%");
_G[self:GetName().."High"]:SetText("150%");

Scripts.OnValueChanged:
local value = math.floor((self:GetValue() * 100) + 0.5) / 100;
local label = _G[self:GetName().."Text"];
if label then
    label:SetText((MBB_OPTIONS_BUTTONSCALE or "Button size:") .. " " .. math.floor(value * 100 + 0.5) .. "%");
end

Scripts.OnEnter:
GameTooltip:SetOwner(self, "ANCHOR_RIGHT");
GameTooltip:SetText(MBB_PROFILE_BUTTON or "Profiles", 1, 1, 1);
if MBB_Profile_GetActiveDisplayName then
    GameTooltip:AddLine((MBB_PROFILE_CURRENT or "Current profile:") .. " " .. MBB_Profile_GetActiveDisplayName(), 1, 0.82, 0);
end
GameTooltip:AddLine(MBB_PROFILE_DESC or "Profiles save layout, scale, position and button order. Excluded buttons remain character-specific.", nil, nil, nil, true);
GameTooltip:Show();

Scripts.OnClick:
MBB_OptionsFrame:Hide();
MBB_Options.CollapseTimeout = MBB_OptionsFrame_TimeoutSlider:GetValue();
if( MBB_OptionsFrame_LeftRadio:GetChecked() ) then
	MBB_Options.ExpandDirection = 1;
elseif( MBB_OptionsFrame_TopRadio:GetChecked() ) then
	MBB_Options.ExpandDirection = 2;
elseif( MBB_OptionsFrame_RightRadio:GetChecked() ) then
	MBB_Options.ExpandDirection = 3;
elseif( MBB_OptionsFrame_BottomRadio:GetChecked() ) then
	MBB_Options.ExpandDirection = 4;
end
if( tonumber(MBB_OptionsFrame_MaxButtonsTextBox:GetText()) ) then
	MBB_Options.MaxButtonsPerLine = tonumber(MBB_OptionsFrame_MaxButtonsTextBox:GetText());
end
if( MBB_OptionsFrame_LeftAltRadio:GetChecked() ) then
	MBB_Options.AltExpandDirection = 1;
elseif( MBB_OptionsFrame_TopAltRadio:GetChecked() ) then
	MBB_Options.AltExpandDirection = 2;
elseif( MBB_OptionsFrame_RightAltRadio:GetChecked() ) then
	MBB_Options.AltExpandDirection = 3;
elseif( MBB_OptionsFrame_BottomAltRadio:GetChecked() ) then
	MBB_Options.AltExpandDirection = 4;
end
-- 3.3.5a port: sliders do not snap to their step while dragging
MBB_Options.ButtonScale = math.floor(MBB_OptionsFrame_ButtonScaleSlider:GetValue() * 20 + 0.5) / 20;
-- 3.3.5a fix: re-anchor for the new size, so the button keeps its place on the ring
MBB_SetButtonPosition();
MBB_SetPositions();

Scripts.OnShow:
				MBB_RestoreOptionsFramePosition();
				MBB_OptionsFrame_HeaderText:SetText("MBB" .. " " .. MBB_OPTIONS_HEADER);
				MBB_UpdateAltRadioButtons();
				MBB_UpdatePositionOptionControls();
                if MBB_ProfileDropdown_Refresh then MBB_ProfileDropdown_Refresh(); end
